WITH promo_agg AS ( SELECT p_item_sk, sum(p_cost) AS total_promo_cost FROM promotion GROUP BY p_item_sk ) SELECT s.s_store_id, cc.cc_call_center_id, ws.web_site_id, i.i_item_id, SUM(wr.wr_return_amt) AS total_return_amount, COUNT(DISTINCT wp.wp_web_page_id) AS distinct_pages, CASE WHEN SUM(wr.wr_return_amt) > 1000 THEN 'HIGH' ELSE 'LOW' END AS return_level, pa.total_promo_cost, AVG(i.i_current_price) AS avg_price, (SELECT MAX(d_year) FROM date_dim) AS latest_year FROM web_returns wr JOIN date_dim d ON wr.wr_returned_date_sk = d.d_date_sk JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN promotion p ON p.p_item_sk = i.i_item_sk JOIN promo_agg pa ON pa.p_item_sk = i.i_item_sk JOIN web_page wp ON wr.wr_web_page_sk = wp.wp_web_page_sk JOIN store s ON s.s_closed_date_sk = d.d_date_sk JOIN call_center cc ON cc.cc_closed_date_sk = d.d_date_sk JOIN web_site ws ON ws.web_close_date_sk = d.d_date_sk JOIN household_demographics hd_refunded ON wr.wr_refunded_hdemo_sk = hd_refunded.hd_demo_sk JOIN household_demographics hd_returning ON wr.wr_returning_hdemo_sk = hd_returning.hd_demo_sk JOIN customer_address ca_refunded ON wr.wr_refunded_addr_sk = ca_refunded.ca_address_sk JOIN customer_address ca_returning ON wr.wr_returning_addr_sk = ca_returning.ca_address_sk WHERE i.i_current_price > (SELECT AVG(i2.i_current_price) FROM item i2) AND d.d_year = 2001 GROUP BY s.s_store_id, cc.cc_call_center_id, ws.web_site_id, i.i_item_id, pa.total_promo_cost LIMIT 100
